<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {api} from './api'
const props=defineProps({channel:{type:String,default:'telegram'}})
const campaigns=ref([]),accounts=ref([]),fields=ref([]),selected=ref(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const campaignOpen=ref(false),stepOpen=ref(false),editingStep=ref(null),showStepEmoji=ref(false),builder=ref(false),builderStage=ref(1),report=ref(false),runtime=ref(null),expandedRecipient=ref(null),audiencePreview=ref(null),previewLoading=ref(false)
const form=ref({name:'',description:'',channel_account_id:'',audience_type:'all',audience_filter:{logic:'and',rules:[]},scheduled_at:''})
const emojis=['😀','😃','😄','😁','😊','🙂','😉','😍','🥰','😘','😂','🤣','😅','😎','🤩','🥳','🤔','👍','👎','👏','🙌','🙏','💪','👌','✅','❌','⚠️','❤️','💚','💙','🔥','⭐','🎉','🎁','📣','📌','📅','⏰','💬','📞','📧','🔗','🚀','✨']
const filterOperators=[['equals','Equals'],['not_equals','Does not equal'],['contains','Contains'],['not_contains','Does not contain'],['starts_with','Starts with'],['ends_with','Ends with'],['is_empty','Is empty'],['is_not_empty','Is not empty']]
const step=ref({name:'',delay_seconds:0,message_mode:'freeform',message_text:'',parse_mode:'HTML',media_url:'',media_type:'image'})
const channelLabel=computed(()=>props.channel==='telegram'?'Telegram':'WhatsApp')
const activeAccounts=computed(()=>(accounts.value||[]).filter(x=>x.active))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function localInput(v){if(!v)return '';const d=new Date(v);const p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes())}
function schedulePayload(v){return v?new Date(v).toISOString():null}
function accountName(a){return props.channel==='telegram'?(a.name||a.username||('Bot '+a.id)):(a.verified_name||a.display_phone_number||('WhatsApp '+a.id))}
function delayLabel(n){n=Number(n||0);if(!n)return 'Immediately';if(n%86400===0)return (n/86400)+' day'+(n===86400?'':'s')+' later';if(n%3600===0)return (n/3600)+' hour'+(n===3600?'':'s')+' later';if(n%60===0)return (n/60)+' minute'+(n===60?'':'s')+' later';return n+' seconds later'}
async function load(){loading.value=true;error.value='';try{accounts.value=props.channel==='telegram'?await api.telegramBots():await api.whatsappConnections();campaigns.value=await api.messagingCampaigns(props.channel);if(selected.value){const found=campaigns.value.find(x=>x.id===selected.value.id);selected.value=found?await api.messagingCampaign(found.id):null}}catch(e){error.value=e.message}finally{loading.value=false}}
function newCampaign(){form.value={name:'',description:'',channel_account_id:activeAccounts.value[0]?.id||'',audience_type:'all',audience_filter:{logic:'and',rules:[]},scheduled_at:''};fields.value=[];selected.value=null;runtime.value=null;audiencePreview.value=null;report.value=false;builderStage.value=1;builder.value=true}
async function saveCampaign(){if(!form.value.name.trim()||!form.value.channel_account_id)return;saving.value=true;error.value='';success.value='';try{const payload={name:form.value.name.trim(),description:form.value.description||null,channel:props.channel,channel_account_id:Number(form.value.channel_account_id),audience_type:form.value.audience_type,audience_filter:form.value.audience_type==='filtered'?form.value.audience_filter:null,scheduled_at:schedulePayload(form.value.scheduled_at)};const editing=!!selected.value?.id;const saved=editing?await api.updateMessagingCampaign(selected.value.id,payload):await api.createMessagingCampaign(payload);campaignOpen.value=false;success.value=editing?'Campaign details updated.':'Campaign draft created.';selected.value=await api.messagingCampaign(saved.id);form.value={name:selected.value.name||'',description:selected.value.description||'',channel_account_id:selected.value.channel_account_id||'',audience_type:selected.value.audience_type||'all',audience_filter:selected.value.audience_filter||{logic:'and',rules:[]},scheduled_at:localInput(selected.value.scheduled_at)};campaigns.value=await api.messagingCampaigns(props.channel);builderStage.value=2}catch(e){error.value=e.message}finally{saving.value=false}}
async function openCampaign(c){error.value='';success.value='';selected.value=await api.messagingCampaign(c.id);form.value={name:selected.value.name||'',description:selected.value.description||'',channel_account_id:selected.value.channel_account_id||'',audience_type:selected.value.audience_type||'all',audience_filter:selected.value.audience_filter||{logic:'and',rules:[]},scheduled_at:localInput(selected.value.scheduled_at)};await loadFields();if(selected.value.status==='draft'){report.value=false;builderStage.value=2;builder.value=true}else{builder.value=false;report.value=true;runtime.value=await api.campaignRuntime(c.id)}}
async function refreshRuntime(){if(!selected.value?.id)return;runtime.value=await api.campaignRuntime(selected.value.id);selected.value=await api.messagingCampaign(selected.value.id);campaigns.value=await api.messagingCampaigns(props.channel)}
function recipientDeliveries(r){return (runtime.value?.deliveries||[]).filter(d=>d.recipient_id===r.id)}
function stepStats(s){const ds=(runtime.value?.deliveries||[]).filter(d=>d.step_id===s.id);return{sent:ds.filter(d=>d.status==='sent').length,failed:ds.filter(d=>d.status==='failed').length,pending:ds.filter(d=>['pending','sending'].includes(d.status)).length,total:ds.length}}
function recipientProgress(r){const ds=recipientDeliveries(r),sent=ds.filter(d=>d.status==='sent').length;return sent+'/'+(selected.value?.steps?.length||0)}
function statusLabel(v){return String(v||'').replaceAll('_',' ')}
async function loadFields(){if(!form.value.channel_account_id){fields.value=[];return}try{fields.value=props.channel==='telegram'?await api.broadcastTelegramFields(Number(form.value.channel_account_id)):await api.broadcastWhatsAppFields(Number(form.value.channel_account_id))}catch(e){error.value=e.message;fields.value=[]}}
function operatorNeedsValue(op){return !['is_empty','is_not_empty'].includes(op)}
function addAudienceRule(){form.value.audience_filter.rules.push({field:fields.value[0]?.key||'first_name',operator:'equals',value:''})}
function removeAudienceRule(i){form.value.audience_filter.rules.splice(i,1)}
async function audienceTypeChanged(){if(form.value.audience_type==='filtered'){await loadFields();if(!form.value.audience_filter.rules.length)addAudienceRule()}}
async function accountChanged(){await loadFields()}

function insertStepText(token){const el=document.querySelector('.campaign-message');if(!el){step.value.message_text+=token;return}const start=el.selectionStart??step.value.message_text.length,end=el.selectionEnd??start;step.value.message_text=step.value.message_text.slice(0,start)+token+step.value.message_text.slice(end);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(start+token.length,start+token.length)})}
function insertStepEmoji(e){insertStepText(e);showStepEmoji.value=false}
function insertStepField(key){insertStepText('%'+key+'%')}
function wrapStep(open,close=open){const el=document.querySelector('.campaign-message');if(!el)return;const s=el.selectionStart,e=el.selectionEnd,t=step.value.message_text;step.value.message_text=t.slice(0,s)+open+t.slice(s,e)+close+t.slice(e);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(s+open.length,e+open.length)})}
function newStep(){editingStep.value=null;showStepEmoji.value=false;step.value={name:'Message '+((selected.value?.steps?.length||0)+1),delay_seconds:0,message_mode:'freeform',message_text:'',parse_mode:'HTML',media_url:'',media_type:'image'};stepOpen.value=true}
function editStep(s){editingStep.value=s.id;showStepEmoji.value=false;step.value={name:s.name,delay_seconds:s.delay_seconds,message_mode:s.message_mode,message_text:s.message_text,parse_mode:s.parse_mode||'HTML',media_url:s.media_url||'',media_type:s.media_type||'image'};stepOpen.value=true}
async function saveStep(){if(!selected.value||!step.value.name.trim()||!step.value.message_text.trim())return;saving.value=true;error.value='';try{const payload={...step.value,name:step.value.name.trim(),delay_seconds:Number(step.value.delay_seconds||0),media_url:step.value.media_url||null,media_type:step.value.media_url?step.value.media_type:null};if(editingStep.value)await api.updateMessagingCampaignStep(selected.value.id,editingStep.value,payload);else await api.addMessagingCampaignStep(selected.value.id,payload);selected.value=await api.messagingCampaign(selected.value.id);campaigns.value=await api.messagingCampaigns(props.channel);stepOpen.value=false;success.value='Campaign step saved.'}catch(e){error.value=e.message}finally{saving.value=false}}
async function removeStep(s){if(!confirm('Delete “'+s.name+'” from this campaign?'))return;try{await api.deleteMessagingCampaignStep(selected.value.id,s.id);selected.value=await api.messagingCampaign(selected.value.id);await load()}catch(e){error.value=e.message}}
async function moveStep(s,direction){try{await api.moveMessagingCampaignStep(selected.value.id,s.id,direction);selected.value=await api.messagingCampaign(selected.value.id);await load()}catch(e){error.value=e.message}}
async function removeCampaign(c){if(!confirm('Delete campaign “'+c.name+'”?'))return;try{await api.deleteMessagingCampaign(c.id);if(selected.value?.id===c.id)selected.value=null;await load();success.value='Campaign deleted.'}catch(e){error.value=e.message}}
async function loadAudiencePreview(){if(!selected.value?.id)return;previewLoading.value=true;error.value='';try{audiencePreview.value=await api.campaignAudiencePreview(selected.value.id)}catch(e){error.value=e.message;audiencePreview.value=null}finally{previewLoading.value=false}}
async function goReview(){builderStage.value=3;await loadAudiencePreview()}
async function saveReviewDraft(){
  if(!selected.value?.id)return
  saving.value=true;error.value='';success.value=''
  try{
    const payload={name:form.value.name.trim(),description:form.value.description||null,channel:props.channel,channel_account_id:Number(form.value.channel_account_id),audience_type:form.value.audience_type,audience_filter:form.value.audience_type==='filtered'?form.value.audience_filter:null,scheduled_at:schedulePayload(form.value.scheduled_at)}
    const saved=await api.updateMessagingCampaign(selected.value.id,payload)
    selected.value=await api.messagingCampaign(saved.id)
    form.value.scheduled_at=localInput(selected.value.scheduled_at)
    campaigns.value=await api.messagingCampaigns(props.channel)
    success.value='Campaign draft saved.'
    builder.value=false
  }catch(e){error.value=e.message}finally{saving.value=false}
}
async function runtimeAction(action,campaign=selected.value){if(!campaign)return;error.value='';success.value='';try{if(action==='launch'){const scheduled=form.value.scheduled_at&&form.value.scheduled_at!=='schedule';const verb=scheduled?'Schedule':'Launch';if(!confirm(verb+' “'+campaign.name+'” to '+(audiencePreview.value?.ready??'the validated')+' recipient(s)?'))return;if(campaign.status==='draft'&&campaign.id===selected.value?.id){const payload={name:form.value.name.trim(),description:form.value.description||null,channel:props.channel,channel_account_id:Number(form.value.channel_account_id),audience_type:form.value.audience_type,audience_filter:form.value.audience_type==='filtered'?form.value.audience_filter:null,scheduled_at:scheduled?schedulePayload(form.value.scheduled_at):null};await api.updateMessagingCampaign(campaign.id,payload)}await api.launchMessagingCampaign(campaign.id);success.value=scheduled?'Campaign scheduled.':'Campaign launched.'}else if(action==='pause'){await api.pauseMessagingCampaign(campaign.id);success.value='Campaign paused.'}else if(action==='resume'){await api.resumeMessagingCampaign(campaign.id);success.value='Campaign resumed.'}else if(action==='cancel'){if(!confirm('Cancel “'+campaign.name+'”? Pending messages will not be sent.'))return;await api.cancelMessagingCampaign(campaign.id);success.value='Campaign cancelled.'}await load();if((builder.value||report.value)&&campaign.id){selected.value=await api.messagingCampaign(campaign.id);if(report.value)runtime.value=await api.campaignRuntime(campaign.id)}}catch(e){error.value=e.message}}
watch(()=>props.channel,()=>{selected.value=null;runtime.value=null;report.value=false;campaignOpen.value=false;stepOpen.value=false;builder.value=false;load()})
onMounted(load)
</script>
<template>
<section class="campaign-engine">
  <template v-if="report && selected">
    <div class="builder-top"><button class="back" @click="report=false">← Campaigns</button><div><small>CAMPAIGN REPORT</small><h2>{{selected.name}}</h2><p class="report-sub">{{selected.description||'No description'}}</p></div><div class="report-controls"><button @click="refreshRuntime">Refresh</button><button v-if="selected.status==='running'||selected.status==='scheduled'" @click="runtimeAction('pause')">Pause</button><button v-if="selected.status==='paused'" class="primary" @click="runtimeAction('resume')">Resume</button><button v-if="['running','scheduled','paused'].includes(selected.status)" class="danger" @click="runtimeAction('cancel')">Cancel</button></div></div>
    <p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>
    <div class="report-summary">
      <div><small>STATUS</small><strong class="status-text">{{statusLabel(selected.status)}}</strong></div>
      <div><small>RECIPIENTS</small><strong>{{runtime?.recipients?.length||0}}</strong></div>
      <div><small>COMPLETED</small><strong>{{(runtime?.recipients||[]).filter(r=>r.status==='completed').length}}</strong></div>
      <div><small>IN PROGRESS</small><strong>{{(runtime?.recipients||[]).filter(r=>['pending','running'].includes(r.status)).length}}</strong></div>
      <div><small>FAILED</small><strong>{{(runtime?.recipients||[]).filter(r=>r.status==='failed').length}}</strong></div>
    </div>

    <div class="report-card">
      <div class="section-head"><div><h3>Message performance</h3><p>Delivery state for each step in the campaign sequence.</p></div></div>
      <div v-for="(s,i) in selected.steps" :key="s.id" class="performance-row">
        <div class="step-num">{{i+1}}</div><div class="performance-main"><strong>{{s.name}}</strong><small>{{delayLabel(s.delay_seconds)}} · {{s.message_text}}</small></div>
        <div class="metric"><b>{{stepStats(s).sent}}</b><span>Sent</span></div><div class="metric"><b>{{stepStats(s).pending}}</b><span>Pending</span></div><div class="metric failed"><b>{{stepStats(s).failed}}</b><span>Failed</span></div>
      </div>
    </div>

    <div class="report-card">
      <div class="section-head"><div><h3>Recipients</h3><p>Each recipient progresses independently through the campaign.</p></div></div>
      <div class="recipient-table">
        <div class="recipient-head"><span>Recipient</span><span>Destination</span><span>Progress</span><span>Status</span><span>Started</span><span>Completed</span><span></span></div>
        <template v-for="r in runtime?.recipients||[]" :key="r.id">
          <div class="recipient-row" @click="expandedRecipient=expandedRecipient===r.id?null:r.id"><strong>{{r.display_name||'Contact '+r.contact_id}}</strong><span>{{r.destination}}</span><span>{{recipientProgress(r)}}</span><span><i class="status-dot" :class="r.status"></i>{{statusLabel(r.status)}}</span><span>{{fmt(r.started_at)}}</span><span>{{fmt(r.completed_at)}}</span><button>{{expandedRecipient===r.id?'⌃':'⌄'}}</button></div>
          <div v-if="expandedRecipient===r.id" class="recipient-detail">
            <div v-for="d in recipientDeliveries(r)" :key="d.id" class="delivery-line"><b>{{d.step_position}}</b><div><strong>{{selected.steps?.find(s=>s.id===d.step_id)?.name||('Message '+d.step_position)}}</strong><small>{{statusLabel(d.status)}} · {{d.sent_at?fmt(d.sent_at):('Due '+fmt(d.due_at))}}<template v-if="d.attempts"> · {{d.attempts}} attempt{{d.attempts===1?'':'s'}}</template></small><p v-if="d.last_error">{{d.last_error}}</p></div></div>
            <div v-if="r.last_error" class="recipient-error">{{r.last_error}}</div>
          </div>
        </template>
        <div v-if="!runtime?.recipients?.length" class="empty inner">No recipient snapshot is available for this campaign.</div>
      </div>
    </div>
  </template>

  <template v-else-if="!builder">
    <div class="toolbar"><div><strong>Campaign workspace</strong><span>{{campaigns.length}} campaign{{campaigns.length===1?'':'s'}}</span></div><button class="primary" @click="newCampaign">+ New Campaign</button></div>
    <p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>
    <div class="card">
      <div v-if="loading" class="empty">Loading campaigns…</div>
      <div v-else-if="!campaigns.length" class="empty"><strong>No {{channelLabel}} campaigns yet.</strong><p>Create a campaign, then add the messages that should run in sequence.</p></div>
      <div v-for="c in campaigns" :key="c.id" class="row" @click="openCampaign(c)"><div class="title"><strong>{{c.name}}</strong><small>{{c.description||'No description'}} · {{c.step_count}} step{{c.step_count===1?'':'s'}}</small></div><span class="pill">{{c.status}}</span><span>{{fmt(c.updated_at)}}</span><div class="row-actions"><button v-if="c.status==='draft' && c.step_count" class="primary compact" @click.stop="openCampaign(c)">Review</button><button v-if="c.status==='running'||c.status==='scheduled'" @click.stop="runtimeAction('pause',c)">Pause</button><button v-if="c.status==='paused'" @click.stop="runtimeAction('resume',c)">Resume</button><button v-if="['running','scheduled','paused'].includes(c.status)" class="danger" @click.stop="runtimeAction('cancel',c)">Cancel</button><button v-if="c.status==='draft'" class="danger" @click.stop="removeCampaign(c)">Delete</button></div><button class="chev">›</button></div>
    </div>
  </template>

  <template v-else>
    <div class="builder-top"><button class="back" @click="builder=false">← Campaigns</button><div><small>{{selected?'EDIT CAMPAIGN':'NEW '+channelLabel.toUpperCase()+' CAMPAIGN'}}</small><h2>{{selected?.name||'Create campaign'}}</h2></div></div>
    <div class="stagebar"><button :class="{active:builderStage===1,done:builderStage>1}" @click="builderStage=1"><b>1</b> Campaign details</button><button :disabled="!selected" :class="{active:builderStage===2}" @click="builderStage=2"><b>2</b> Message sequence</button><button :disabled="!selected" :class="{active:builderStage===3}" @click="builderStage=3"><b>3</b> Timing & review</button></div>
    <p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>

    <div v-if="builderStage===1" class="builder-card">
      <div class="section-head"><div><h3>Campaign details</h3><p>Choose the channel account and audience for this campaign.</p></div></div>
      <label>Campaign name<input v-model="form.name" placeholder="e.g. September re-engagement"></label>
      <label>Description<textarea v-model="form.description" rows="3" placeholder="Optional internal description"></textarea></label>
      <div class="grid2"><label>{{channelLabel}} account<select v-model="form.channel_account_id" @change="accountChanged"><option value="" disabled>Select account…</option><option v-for="a in activeAccounts" :key="a.id" :value="a.id">{{accountName(a)}}</option></select></label><label>Audience<select v-model="form.audience_type" @change="audienceTypeChanged"><option value="all">All eligible contacts</option><option value="filtered">Filtered audience</option></select></label></div>
      <div v-if="form.audience_type==='filtered'" class="campaign-filter">
        <div class="filter-head"><strong>Audience rules</strong><select v-model="form.audience_filter.logic"><option value="and">Match ALL rules (AND)</option><option value="or">Match ANY rule (OR)</option></select></div>
        <div v-for="(rule,i) in form.audience_filter.rules" :key="i" class="filter-rule"><select v-model="rule.field"><option v-for="field in fields" :key="field.key" :value="field.key">{{field.label}}</option></select><select v-model="rule.operator"><option v-for="op in filterOperators" :key="op[0]" :value="op[0]">{{op[1]}}</option></select><input v-if="operatorNeedsValue(rule.operator)" v-model="rule.value" placeholder="Value"/><span v-else class="filter-no-value">No value required</span><button type="button" class="danger" @click="removeAudienceRule(i)">×</button></div>
        <button type="button" class="secondary add-rule" @click="addAudienceRule">+ Add rule</button>
      </div>
      <div class="actions"><button @click="builder=false">Cancel</button><button class="primary" :disabled="saving||!form.name.trim()||!form.channel_account_id" @click="saveCampaign">{{saving?'Saving…':'Save & continue →'}}</button></div>
    </div>

    <div v-else-if="builderStage===2 && selected" class="builder-card">
      <div class="section-head"><div><h3>Message sequence</h3><p>Messages run from top to bottom. Each delay is measured from the previous step.</p></div><button class="primary" @click="newStep">+ Add message</button></div>
      <div v-if="!selected.steps?.length" class="empty inner">No messages yet. Add the first message to start building this campaign.</div>
      <div v-for="(s,i) in selected.steps" :key="s.id" class="step-card">
        <div class="step-num">{{i+1}}</div><div class="step-main"><div class="step-head"><strong>{{s.name}}</strong><span>{{delayLabel(s.delay_seconds)}}</span></div><div class="message">{{s.message_text}}</div><small v-if="s.media_url">{{s.media_type}} · {{s.media_url}}</small></div>
        <div class="step-actions"><button :disabled="i===0" @click="moveStep(s,'up')">↑</button><button :disabled="i===selected.steps.length-1" @click="moveStep(s,'down')">↓</button><button @click="editStep(s)">Edit</button><button class="danger" @click="removeStep(s)">Delete</button></div>
      </div>
      <div class="actions"><button @click="builderStage=1">← Details</button><button class="primary" :disabled="!selected.steps?.length" @click="goReview">Timing & review →</button></div>
    </div>

    <div v-else-if="builderStage===3 && selected" class="builder-card">
      <div class="section-head"><div><h3>Timing & review</h3><p>Validate the audience, choose when to start, then launch the campaign.</p></div><button @click="loadAudiencePreview" :disabled="previewLoading">{{previewLoading?'Checking…':'Refresh audience'}}</button></div>
      <div class="review-grid"><div><small>CHANNEL</small><strong>{{channelLabel}}</strong></div><div><small>AUDIENCE</small><strong>{{selected.audience_type==='all'?'All eligible contacts':'Filtered audience'}}</strong></div><div><small>MESSAGES</small><strong>{{selected.steps?.length||0}}</strong></div><div><small>STATUS</small><strong>{{selected.status}}</strong></div></div>
      <div class="launch-settings"><label>Start campaign<select :value="form.scheduled_at?'schedule':''" @change="form.scheduled_at=$event.target.value==='schedule'?(form.scheduled_at||localInput(new Date(Date.now()+300000).toISOString())):''"><option value="">Launch immediately</option><option value="schedule">Schedule date & time…</option></select></label><label v-if="form.scheduled_at">Scheduled for<input type="datetime-local" v-model="form.scheduled_at"></label></div>
      <div class="audience-validation">
        <div class="validation-head"><div><strong>Audience validation</strong><small>The launch snapshot will include only contacts that can resolve every message variable.</small></div><span v-if="previewLoading">Checking…</span></div>
        <div v-if="audiencePreview" class="validation-stats"><div><b>{{audiencePreview.evaluated}}</b><span>Evaluated</span></div><div class="ready"><b>{{audiencePreview.ready}}</b><span>Ready</span></div><div :class="{bad:audiencePreview.excluded}"><b>{{audiencePreview.excluded}}</b><span>Excluded</span></div></div>
        <div v-if="audiencePreview?.contacts?.length" class="validation-list"><div v-for="r in audiencePreview.contacts" :key="r.contact_id" class="validation-row"><strong>{{r.display_name}}</strong><span>{{r.destination}}</span><span class="validation-status" :class="r.status">{{r.status}}</span><small>{{r.reasons?.map(x=>x.message).join(', ')||'Ready to receive campaign'}}</small></div></div>
        <div v-else-if="!previewLoading" class="empty inner">No audience preview loaded yet.</div>
      </div>
      <div class="timeline"><div v-for="(s,i) in selected.steps" :key="s.id" class="timeline-row"><b>{{i+1}}</b><div><strong>{{s.name}}</strong><small>{{delayLabel(s.delay_seconds)}}</small><p>{{s.message_text}}</p></div></div></div>
      <div class="runtime-note"><strong>Runtime ready.</strong><span>Launching snapshots the Telegram audience. Each recipient then advances independently through this sequence using the delay after the previous successful message.</span></div>
      <div class="actions"><button @click="builderStage=2">← Sequence</button><button :disabled="saving" @click="saveReviewDraft">{{saving?'Saving…':'Save draft'}}</button><button v-if="selected.status==='draft'" class="primary" :disabled="previewLoading||!audiencePreview?.ready" @click="runtimeAction('launch')">{{form.scheduled_at&&form.scheduled_at!=='schedule'?'Schedule campaign':'Launch campaign'}}</button><button v-if="selected.status==='running'||selected.status==='scheduled'" @click="runtimeAction('pause')">Pause</button><button v-if="selected.status==='paused'" class="primary" @click="runtimeAction('resume')">Resume</button><button v-if="['running','scheduled','paused'].includes(selected.status)" class="danger" @click="runtimeAction('cancel')">Cancel</button></div>
    </div>
  </template>

  <div v-if="stepOpen" class="overlay" @click.self="stepOpen=false"><div class="modal"><div class="modal-head"><div><small>CAMPAIGN MESSAGE</small><h2>{{editingStep?'Edit':'Add'}} message</h2></div><button @click="stepOpen=false">×</button></div><label>Step name<input v-model="step.name"></label><label>Delay after previous step<select v-model.number="step.delay_seconds"><option :value="0">Immediately</option><option :value="300">5 minutes</option><option :value="3600">1 hour</option><option :value="21600">6 hours</option><option :value="86400">1 day</option><option :value="172800">2 days</option><option :value="604800">7 days</option></select></label><label>Message<div class="editor-tools"><template v-if="props.channel==='telegram'"><button type="button" @click="wrapStep('<b>','</b>')"><b>B</b></button><button type="button" @click="wrapStep('<i>','</i>')"><i>I</i></button><button type="button" @click="wrapStep('<u>','</u>')"><u>U</u></button><button type="button" @click="wrapStep('<s>','</s>')"><s>S</s></button><button type="button" @click="wrapStep('<a href=&quot;https://example.com&quot;>','</a>')">🔗 Link</button></template><span class="emoji-wrap"><button type="button" @click="showStepEmoji=!showStepEmoji">😊 ▾</button><span v-if="showStepEmoji" class="emoji-picker"><button v-for="e in emojis" :key="e" type="button" @click="insertStepEmoji(e)">{{e}}</button></span></span><select @change="if($event.target.value){insertStepField($event.target.value);$event.target.value=''}"><option value="">Insert Field…</option><option v-for="field in fields" :key="field.key" :value="field.key">{{field.label}} (%{{field.key}}%)</option></select></div><textarea class="campaign-message" v-model="step.message_text" maxlength="4096" rows="7" :placeholder="props.channel==='telegram'?'Hi %first_name%, ...':'Hi %name%, ...'"></textarea><small>{{props.channel==='telegram'?'Telegram rich text supported.':'WhatsApp free-form text.'}} Fields are rendered separately for every recipient.</small></label><div class="grid2"><label>Media URL<input v-model="step.media_url" placeholder="Optional"></label><label>Media type<select v-model="step.media_type"><option value="image">Image</option><option value="video">Video</option><option value="document">Document</option></select></label></div><p class="hint">Variables and provider-specific template controls will use the same field/template infrastructure as Broadcasts when campaign delivery is connected.</p><div class="actions"><button @click="stepOpen=false">Cancel</button><button class="primary" :disabled="saving||!step.name.trim()||!step.message_text.trim()" @click="saveStep">{{saving?'Saving…':'Save message'}}</button></div></div></div>
</section>
